import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// @ts-expect-error — plain ESM build script without type declarations.
import { buildColorsInventory } from '../bin/build-colors-json.mjs';
import { COLOR_RENAME_MAP, isNewColorName, retiredColorNames } from '../src/color-rename.js';

/**
 * `src/colors.json` is generated by `bin/build-colors-json.mjs` (Sass colour dump + catalogs) and
 * committed; the JS mirrors in `src/tokens.ts` read it. This test regenerates it in memory and
 * fails when the committed file drifts — run `npm run build:colors --workspace=@tgmc/theme` and
 * commit the result (colour system Task 8, R-T8h).
 */
const committed = JSON.parse(readFileSync(join(import.meta.dirname, '../src/colors.json'), 'utf8')) as {
  cssVariables: Record<'light' | 'dark', Record<string, string>>;
};

describe('colors.json', () => {
  it('matches a fresh build (no drift)', () => {
    expect(buildColorsInventory()).toEqual(committed);
  });

  it('publishes cssVariables under the new --theme-…-color names only (R-T8c)', () => {
    const old = new Set([...Object.keys(COLOR_RENAME_MAP.renames), ...retiredColorNames()]);
    for (const mode of ['light', 'dark'] as const) {
      const keys = Object.keys(committed.cssVariables[mode]);
      expect(
        keys.filter((k) => old.has(k)),
        mode
      ).toEqual([]);
      for (const key of keys) expect(isNewColorName(key), `${mode} ${key}`).toBe(true);
    }
  });
});
